import { NextResponse } from 'next/server'
import { db } from '@/lib/db'

export async function GET() {
  try {
    const [
      totalNurses,
      approvedNurses,
      pendingNurses,
      totalBeneficiaries,
      totalServices,
      activeServices,
      totalRequests,
      pendingRequests,
      approvedRequests,
      completedRequests,
    ] = await Promise.all([
      db.nurse.count(),
      db.nurse.count({ where: { status: 'approved' } }),
      db.nurse.count({ where: { status: 'pending' } }),
      db.beneficiary.count(),
      db.service.count(),
      db.service.count({ where: { isActive: true } }),
      db.serviceRequest.count(),
      db.serviceRequest.count({ where: { status: 'pending' } }),
      db.serviceRequest.count({ where: { status: 'approved' } }),
      db.serviceRequest.count({ where: { status: 'completed' } }),
    ])

    const completedPayments = await db.serviceRequest.findMany({
      where: { status: 'completed' },
      include: { service: { select: { price: true } } },
    })

    const totalRevenue = completedPayments.reduce((sum, r) => sum + (r.service?.price || 0), 0)

    return NextResponse.json({
      totalNurses,
      approvedNurses,
      pendingNurses,
      totalBeneficiaries,
      totalServices,
      activeServices,
      totalRequests,
      pendingRequests,
      approvedRequests,
      completedRequests,
      totalRevenue,
    })
  } catch (error) {
    return NextResponse.json({ error: 'حدث خطأ في الخادم' }, { status: 500 })
  }
}
